using System;
using System.Diagnostics;
using System.IO;
using System.Management;
using Microsoft.Win32;
using System.Windows;
namespace WinOptimizer {
 public static class SystemActions {
  public static string DetectWindows(){try{using(var k=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion")){string p=Convert.ToString(k.GetValue("ProductName","Windows"));string v=Convert.ToString(k.GetValue("CurrentVersion",""));if(p.IndexOf("Windows 11",StringComparison.OrdinalIgnoreCase)>=0)return "Windows 11";if(v.StartsWith("6.1"))return "Windows 7";if(v.StartsWith("6.2")||v.StartsWith("6.3"))return "Windows 8 / 8.1";if(v.StartsWith("10."))return "Windows 10 / 11";return p;}}catch{return Environment.OSVersion.VersionString;}}
  public static string DetectGpu(){try{using(var s=new ManagementObjectSearcher("select Name from Win32_VideoController")){foreach(ManagementObject m in s.Get()){string n=Convert.ToString(m["Name"]);if(!String.IsNullOrEmpty(n))return n;}}}catch{}return "Не определена";}
  public static void Run(string exe,string args){string name=Path.GetFileName(exe);if(!String.Equals(name,exe,StringComparison.OrdinalIgnoreCase)||!(name.Equals("powercfg.exe",StringComparison.OrdinalIgnoreCase)||name.Equals("sc.exe",StringComparison.OrdinalIgnoreCase)||name.Equals("wmic.exe",StringComparison.OrdinalIgnoreCase)||name.Equals("ipconfig.exe",StringComparison.OrdinalIgnoreCase)))throw new InvalidOperationException(Localization.T("Запуск этой системной команды не разрешён."));string fullPath=Path.Combine(Environment.SystemDirectory,name);if(!File.Exists(fullPath))throw new FileNotFoundException(Localization.T("Системная команда не найдена."),fullPath);var p=new ProcessStartInfo(fullPath,args);p.UseShellExecute=false;p.CreateNoWindow=true;using(Process x=Process.Start(p)){x.WaitForExit();if(x.ExitCode!=0)throw new Exception(name+Localization.T(" завершился с кодом ")+x.ExitCode);}}
  public static void SetDword(string path,string name,int value){using(var k=Registry.CurrentUser.CreateSubKey(path)){k.SetValue(name,value,RegistryValueKind.DWord);}}
  public static void SetDwordMachine(string path,string name,int value){using(var k=Registry.LocalMachine.CreateSubKey(path)){k.SetValue(name,value,RegistryValueKind.DWord);}}
  public static void CleanTemp(){string local=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);string windows=Environment.GetFolderPath(Environment.SpecialFolder.Windows);string[] paths={String.IsNullOrWhiteSpace(local)?null:Path.Combine(local,"Temp"),String.IsNullOrWhiteSpace(windows)?null:Path.Combine(windows,"Temp")};foreach(string path in paths){if(String.IsNullOrWhiteSpace(path)||!Directory.Exists(path))continue;DirectoryInfo root=new DirectoryInfo(path);if((root.Attributes&FileAttributes.ReparsePoint)!=0)continue;DeleteTempContents(root);}}
  static void DeleteTempContents(DirectoryInfo directory){FileInfo[] files;DirectoryInfo[] folders;try{files=directory.GetFiles();folders=directory.GetDirectories();}catch{return;}foreach(FileInfo file in files){try{file.Delete();}catch{}}foreach(DirectoryInfo folder in folders){try{if((folder.Attributes&FileAttributes.ReparsePoint)!=0)folder.Delete(false);else{DeleteTempContents(folder);folder.Delete(false);}}catch{}}}
  public static void CreateRestorePoint(){try{using(ManagementClass c=new ManagementClass(@"\\.\root\default:SystemRestore")){ManagementBaseObject input=c.GetMethodParameters("CreateRestorePoint");input["Description"]="WinOptimizer — "+Localization.T("точка перед изменениями");input["RestorePointType"]=(uint)12;input["EventType"]=(uint)100;using(ManagementBaseObject output=c.InvokeMethod("CreateRestorePoint",input,null)){if(output==null||Convert.ToUInt32(output["ReturnValue"])!=0)throw new Exception(Localization.T("WMI не смог создать точку восстановления."));}}}catch(Exception e){throw new Exception(Localization.T("Не удалось создать точку восстановления. Проверьте, включена ли защита системы. ")+e.Message);}}
  public static void StopService(string name){if(!String.Equals(name,"SysMain",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException(Localization.T("Изменение этой службы не разрешено."));Run("sc.exe","config \"SysMain\" start= demand");}
 }
}
